fn kit_reference(references:&mut RowIndex<'_>,id:i64,control:&mut SqliteSnapshotControl<'_>)->Result<Owned<store::os_io::ArtifactRef>,ValueError>{
 let row=references.take(id,control)?.ok_or_else(||kit_invalid("dangling or multiply owned Semio kit reference"))?;
